-- services/RoomSurfaces.lua
--
-- The room's per-sprite surfaces (data/room_surfaces.lua, generated by
-- tools/room_surfaces.py): a sprite's top face, footprint and height in
-- its own pixels. This module finds the entry for a PLACED OBJECT, which
-- is the whole difficulty: an object names its art by item id or sprite
-- name, the loader resolves that through aliases.json, and an animated
-- sprite draws one frame of a group.
--
--   name   = obj.sprite or item.sprite or obj.id
--   key    = loader.aliases[name] or name
--   frames = loader.animation_paths[key] or loader.animation_paths[name]
--   file   = frames and frames[frame] or key       (frame pinned: its own;
--                                                   animating: frame 1)
--   entry  = data[file]; a strip's entry.cells[frame]
--
-- Every step is nil-safe: the headless smokes stub the loader without
-- aliases or animation groups, and a build without the data file gets an
-- empty table. No love.* here, so sim can require it.
--
-- Coordinates are SPRITE PIXELS (origin top-left of the PNG, or of the
-- strip cell), native scale. models/room_space.lua turns them into grid
-- units against the way views/RoomView draws the sprite.

local RoomSurfaces = {}

local DATA = nil

-- Load the data (injectable for tests). Missing file -> {}.
function RoomSurfaces.load(data)
    if data then DATA = data; return DATA end
    local good, t = pcall(require, "data.room_surfaces")
    DATA = (good and type(t) == "table") and t or {}
    return DATA
end

local function data()
    if DATA == nil then RoomSurfaces.load() end
    return DATA
end

function RoomSurfaces.meta() return data().__meta end

-- The file key the loader would draw for `name` at `frame` (nil = the
-- animating default, frame 1), and whether the frame was pinned.
function RoomSurfaces.keyFor(loader, name, frame)
    if not name then return nil end
    local aliases = loader and loader.aliases
    local key = (aliases and aliases[name]) or name
    local ap = loader and loader.animation_paths
    local frames = ap and (ap[key] or ap[name])
    if frames and #frames > 0 then
        local i = math.floor(tonumber(frame) or 1)
        if i < 1 then i = 1 end
        if i > #frames then i = #frames end
        return frames[i], key
    end
    return key, key
end

-- The entry by file key; a strip cell by index.
function RoomSurfaces.get(file_key, cell)
    local e = file_key and data()[file_key] or nil
    if e and cell and e.cells then
        local i = math.floor(tonumber(cell) or 1)
        if i < 1 then i = 1 end
        if i > #e.cells then i = #e.cells end
        e = e.cells[i] or e
    end
    return e
end

-- The entry for a placed object (fields sprite / id / frame), or nil.
-- `item` is the catalog item when the caller has it (its sprite field).
function RoomSurfaces.entryFor(loader, obj, item)
    if not obj then return nil end
    local name = obj.sprite or (item and item.sprite) or obj.id
    local file_key = RoomSurfaces.keyFor(loader, name, obj.frame)
    local e = RoomSurfaces.get(file_key, obj.frame)
    if not e and name ~= file_key then e = RoomSurfaces.get(name, obj.frame) end
    return e, file_key
end

function RoomSurfaces.hasFace(entry)
    return entry ~= nil and entry.v == "face" and entry.face ~= nil
end

-- A corner list { Tx,Ty, Lx,Ly, Bx,By, Rx,Ry } -> T, L, B, R as {x, y}.
function RoomSurfaces.corners(list)
    if not list then return nil end
    return { list[1], list[2] }, { list[3], list[4] }, { list[5], list[6] }, { list[7], list[8] }
end

-- What the space model needs of the sprite, from the entry when it has it
-- (cell width and bottom row), else from the drawn sprite.
function RoomSurfaces.geomFor(entry, sprite_w, bottom)
    local cw = entry and entry.cell and entry.cell[1] or sprite_w
    local b  = entry and entry.bottom or bottom
    if not (cw and b) then return nil end
    return { cell_w = cw, bottom = b }
end

return RoomSurfaces
